modules.content:
mock_provider "azurerm" {}

variables {
  name = "func-tp-test"
  resource_group_name = "rg-test"
  location = "westeurope"
  storage_account_name = "sttptest001"
  storage_account_id = "/subscriptions/00000000-0000-0000-0000-000000000000/resourceGroups/rg-test/providers/Microsoft.Storage/storageAccounts/sttptest001"
}

run "ftps_state_is_disabled" {
  command = plan
  assert {
    condition     = azurerm_linux_function_app.this.site_config[0].ftps_state == "Disabled"
    error_message = "FTPS state must be Disabled after the change."
  }
}
